SELECT sno FROM SC WHERE cno = 'C01'
UNION
SELECT sno FROM SC WHERE cno = 'C02';

SELECT s.sname, sc.cno
FROM Student s
JOIN SC sc ON sc.sno = s.sno;

SELECT s.sno, s.sname
FROM Student s
WHERE NOT EXISTS (
  SELECT 1 FROM Course c
  WHERE NOT EXISTS (
    SELECT 1 FROM SC sc
    WHERE sc.sno = s.sno AND sc.cno = c.cno
  )
);

CREATE TABLE Student (
  sno VARCHAR2(8) PRIMARY KEY,
  sname VARCHAR2(40) NOT NULL,
  dept VARCHAR2(30),
  age NUMBER(3) CHECK (age BETWEEN 0 AND 120)
);
CREATE TABLE Course (
  cno VARCHAR2(4) PRIMARY KEY,
  cname VARCHAR2(60) NOT NULL,
  credit NUMBER(3,1) CHECK (credit > 0)
);

ALTER TABLE Student ADD entrance_date DATE;
ALTER TABLE Student MODIFY sname VARCHAR2(60);
ALTER TABLE Student ADD CONSTRAINT uq_student_name UNIQUE (sname);
ALTER TABLE Student DROP CONSTRAINT uq_student_name;
ALTER TABLE Student DROP COLUMN entrance_date;

CREATE INDEX idx_sc_cno ON SC(cno);
CREATE UNIQUE INDEX idx_course_name ON Course(cname);
DROP INDEX idx_course_name;

SELECT c.cno, c.cname, COUNT(sc.sno) AS n
FROM Course c LEFT JOIN SC sc ON sc.cno = c.cno
GROUP BY c.cno, c.cname;

SELECT s.sno, s.sname, sc.grade
FROM Student s
LEFT JOIN SC sc ON sc.sno = s.sno AND sc.cno = 'C01';

SELECT sno, grade FROM SC
WHERE cno = 'C01'
  AND grade = (SELECT MAX(grade) FROM SC WHERE cno = 'C01');

SELECT sc.sno, sc.cno, sc.grade
FROM SC sc
WHERE sc.grade > (
  SELECT AVG(t.grade) FROM SC t WHERE t.cno = sc.cno
);

SELECT s.sno, s.sname FROM Student s
WHERE NOT EXISTS (
  SELECT 1 FROM SC sc WHERE sc.sno = s.sno
);

