UPDATE SC SET grade = 85 WHERE sno = 'S05' AND cno = 'C02';
DELETE FROM SC WHERE sno = 'S05' AND cno = 'C02';

SAVEPOINT before_change;
UPDATE SC SET grade = grade + 2 WHERE grade BETWEEN 0 AND 98;
ROLLBACK TO before_change;
COMMIT;

DECLARE
  v_name Student.sname%TYPE;
BEGIN
  SELECT sname INTO v_name FROM Student WHERE sno = 'S01';
  DBMS_OUTPUT.PUT_LINE(v_name);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('学生不存在');
END;
/

DECLARE
  v_name Student.sname%TYPE;
  v_age Student.age%TYPE;
BEGIN
  SELECT sname, age INTO v_name, v_age
  FROM Student WHERE sno = 'S01';
  DBMS_OUTPUT.PUT_LINE(v_name || ':' || v_age);
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('无此学生');
  WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('查询条件不唯一');
END;
/

IF v_grade < 0 OR v_grade > 100 THEN
  RAISE_APPLICATION_ERROR(-20001, '成绩必须在 0 到 100 之间');
END IF;

IF v_grade IS NULL THEN
  DBMS_OUTPUT.PUT_LINE('未出分');
ELSIF v_grade >= 90 THEN
  DBMS_OUTPUT.PUT_LINE('优秀');
ELSIF v_grade >= 60 THEN
  DBMS_OUTPUT.PUT_LINE('及格');
ELSE
  DBMS_OUTPUT.PUT_LINE('不及格');
END IF;

-- 基本循环：先执行，再由 EXIT WHEN 退出
LOOP
  v_i := v_i + 1;
  EXIT WHEN v_i >= 10;
END LOOP;
-- 条件循环：条件一开始为假则执行零次
WHILE v_i < 10 LOOP
  v_i := v_i + 1;
END LOOP;
-- 数值 FOR：循环变量隐式声明
FOR i IN 1..10 LOOP
  DBMS_OUTPUT.PUT_LINE(i);
END LOOP;

DECLARE
  CURSOR c_scores IS SELECT sno, grade FROM SC WHERE cno = 'C01';
  v_row c_scores%ROWTYPE;
BEGIN
  OPEN c_scores;
  LOOP
    FETCH c_scores INTO v_row;
    EXIT WHEN c_scores%NOTFOUND;
    DBMS_OUTPUT.PUT_LINE(v_row.sno || ':' || v_row.grade);
  END LOOP;
  CLOSE c_scores;
END;
/

DECLARE
  CURSOR c_scores(p_cno SC.cno%TYPE) IS
    SELECT sno, grade FROM SC WHERE cno = p_cno;
BEGIN
  FOR r IN c_scores('C01') LOOP
    DBMS_OUTPUT.PUT_LINE(r.sno || ':' || r.grade);
  END LOOP;
END;
/

CREATE OR REPLACE PROCEDURE get_course_count (
  p_sno IN Student.sno%TYPE,
  p_count OUT NUMBER
) AS
BEGIN
  SELECT COUNT(*) INTO p_count FROM SC WHERE sno = p_sno;
END;
/
DECLARE
  v_count NUMBER;
BEGIN
  get_course_count('S01', v_count);
  DBMS_OUTPUT.PUT_LINE(v_count);
END;
/

CREATE OR REPLACE FUNCTION course_average (
  p_cno IN Course.cno%TYPE
) RETURN NUMBER AS
  v_avg NUMBER;
BEGIN
  SELECT AVG(grade) INTO v_avg FROM SC WHERE cno = p_cno;
  RETURN v_avg;
END;
/
SELECT course_average('C01') AS avg_grade FROM dual;

CREATE TABLE GradeAudit (
  sno VARCHAR2(8), cno VARCHAR2(4),
  old_grade NUMBER(5,2), new_grade NUMBER(5,2), changed_at DATE
);
CREATE OR REPLACE TRIGGER trg_grade_audit
AFTER UPDATE OF grade ON SC
FOR EACH ROW
BEGIN
  INSERT INTO GradeAudit(sno,cno,old_grade,new_grade,changed_at)
  VALUES(:OLD.sno,:OLD.cno,:OLD.grade,:NEW.grade,SYSDATE);
END;
/
